fn leaf_nodes(g) {
    leaves = []
    all_edges = g.edges()
    for id in g.nodes() {
        # A leaf has no outgoing edges
        has_outgoing = false
        for e in all_edges {
            if e[0] == id {
                has_outgoing = true
            }
        }
        if not has_outgoing {
            leaves.append!(id)
        }
    }
    return leaves
}

