fn node_degrees(g) {
    degrees = {}
    all_edges = g.edges()
    for id in g.nodes() {
        out_degree = 0
        in_degree = 0
        for edge in all_edges {
            if edge[0] == id {
                out_degree = out_degree + 1
            }
            if edge[1] == id {
                in_degree = in_degree + 1
            }
        }
        degrees[id] = {"in": in_degree, "out": out_degree}
    }
    return degrees
}

